import type { BaseTextAttributes } from '@blocksuite/store';
import { html } from 'lit';
import { styleMap } from 'lit/directives/style-map.js';

import type { AttributeRenderer } from '../types.js';

function inlineTextStyles(
  props: BaseTextAttributes
): ReturnType<typeof styleMap> {
  let textDecorations = '';
  if (props.underline) {
    textDecorations += 'underline';
  }
  if (props.strike) {
    textDecorations += ' line-through';
  }

  let inlineCodeStyle = {};
  if (props.code) {
    inlineCodeStyle = {
      'font-family':
        '"SFMono-Regular", Menlo, Consolas, "PT Mono", "Liberation Mono", Courier, monospace',
      'line-height': 'normal',
      background: 'rgba(135,131,120,0.15)',
      color: '#EB5757',
      'border-radius': '3px',
      'font-size': '85%',
      padding: '0.2em 0.4em',
    };
  }

  return styleMap({
    'font-weight': props.bold ? 'bold' : 'inherit',
    'font-style': props.italic ? 'italic' : 'inherit',
    'text-decoration': textDecorations.length > 0 ? textDecorations : 'inherit',
    ...inlineCodeStyle,
  });
}

export const getDefaultAttributeRenderer =
  <T extends BaseTextAttributes>(): AttributeRenderer<T> =>
  ({ delta }) => {
    const style = delta.attributes
      ? inlineTextStyles(delta.attributes)
      : styleMap({});
    return html`<span style=${style}
      ><v-text .str=${delta.insert}></v-text
    ></span>`;
  };

import { describe, expect, test } from 'vitest';

import * as turboRendererModule from '../../../../gfx/turbo-renderer/src/turbo-renderer.js';

describe('viewport turbo renderer policy', () => {
  test.each([
    { isIOS: true, zoom: 0.4, hasBitmap: true, expected: true },
    { isIOS: true, zoom: 0.4, hasBitmap: false, expected: false },
    { isIOS: false, zoom: 0.4, hasBitmap: true, expected: false },
    { isIOS: true, zoom: 0.8, hasBitmap: true, expected: false },
  ])(
    'prefers cached bitmap only for iOS low-zoom gestures with a bitmap %#',
    ({ isIOS, zoom, hasBitmap, expected }) => {
      expect(
        'shouldPreferBitmapCacheDuringLowZoomGesture' in turboRendererModule
      ).toBe(true);

      const shouldPreferBitmapCacheDuringLowZoomGesture = (
        turboRendererModule as {
          shouldPreferBitmapCacheDuringLowZoomGesture: (params: {
            isIOS: boolean;
            zoom: number;
            hasBitmap: boolean;
          }) => boolean;
        }
      ).shouldPreferBitmapCacheDuringLowZoomGesture;

      expect(
        shouldPreferBitmapCacheDuringLowZoomGesture({
          isIOS,
          zoom,
          hasBitmap,
        })
      ).toBe(expected);
    }
  );

  test.each([
    { isIOS: true, zoom: 0.4, expected: false },
    { isIOS: true, zoom: 0.8, expected: true },
    { isIOS: false, zoom: 0.4, expected: true },
  ])(
    'idles turbo blocks outside iOS low-zoom survival mode %#',
    ({ isIOS, zoom, expected }) => {
      expect('shouldIdleTurboBlocksDuringZooming' in turboRendererModule).toBe(
        true
      );

      const shouldIdleTurboBlocksDuringZooming = (
        turboRendererModule as {
          shouldIdleTurboBlocksDuringZooming: (params: {
            isIOS: boolean;
            zoom: number;
          }) => boolean;
        }
      ).shouldIdleTurboBlocksDuringZooming;

      expect(
        shouldIdleTurboBlocksDuringZooming({
          isIOS,
          zoom,
        })
      ).toBe(expected);
    }
  );
});

use crossterm::event::{DisableMouseCapture, EnableMouseCapture};
use crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Layout};
use ratatui::style::{Color, Style};
use ratatui::widgets::{Block, Borders};
use ratatui::Terminal;
use std::io;
use tui_textarea::{Input, Key, TextArea};

fn validate(textarea: &mut TextArea) -> bool {
    if let Err(err) = textarea.lines()[0].parse::<f64>() {
        textarea.set_style(Style::default().fg(Color::LightRed));
        textarea.set_block(
            Block::default()
                .borders(Borders::ALL)
                .border_style(Color::LightRed)
                .title(format!("ERROR: {}", err)),
        );
        false
    } else {
        textarea.set_style(Style::default().fg(Color::LightGreen));
        textarea.set_block(
            Block::default()
                .border_style(Color::LightGreen)
                .borders(Borders::ALL)
                .title("OK"),
        );
        true
    }
}

fn main() -> io::Result<()> {
    let stdout = io::stdout();
    let mut stdout = stdout.lock();

    enable_raw_mode()?;
    crossterm::execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut term = Terminal::new(backend)?;

    let mut textarea = TextArea::default();
    textarea.set_cursor_line_style(Style::default());
    textarea.set_placeholder_text("Enter a valid float (e.g. 1.56)");
    let layout = Layout::default().constraints([Constraint::Length(3), Constraint::Min(1)]);
    let mut is_valid = validate(&mut textarea);

    loop {
        term.draw(|f| {
            let chunks = layout.split(f.area());
            f.render_widget(&textarea, chunks[0]);
        })?;

        match crossterm::event::read()?.into() {
            Input { key: Key::Esc, .. } => break,
            Input {
                key: Key::Enter, ..
            } if is_valid => break,
            Input {
                key: Key::Char('m'),
                ctrl: true,
                ..
            }
            | Input {
                key: Key::Enter, ..
            } => {}
            input => {
                // TextArea::input returns if the input modified its text
                if textarea.input(input) {
                    is_valid = validate(&mut textarea);
                }
            }
        }
    }

    disable_raw_mode()?;
    crossterm::execute!(
        term.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    term.show_cursor()?;

    println!("Input: {:?}", textarea.lines()[0]);
    Ok(())
}

